  "PageHeader": {
    "name": "PageHeader",
    "props": {
      "title": {
        "kind": "unknown",
        "design": "plumbing",
        "description": "Page title (rendered as TypographyH2 — the current page; it never appears in the breadcrumb)."
      },
      "breadcrumbs": {
        "kind": "unknown",
        "design": "plumbing",
        "optional": true,
        "description": "Ancestor trail, MAX TWO ({label, href?}[]). Ancestors only — BreadcrumbPage is deliberately unused. Crumb-less pages (the trail's root, e.g. All Locations) still RESERVE the trail row's height (invisible spacer) so the header band matches every other page and nothing jumps on navigation. (default [])"
      },
      "description": {
        "kind": "unknown",
        "design": "plumbing",
        "optional": true,
        "description": "Subtitle line under the H2 (muted, measured). Every proposal page should carry one. String or node. (default none)"
      },
      "lastUpdated": {
        "kind": "string",
        "design": "knob",
        "optional": true,
        "description": "Timestamp shown muted beneath the description. Pass \"auto\" to BIND data.aiInsights.lastUpdated (the AI Insights pages own it — it was removed from the AreaInsights header so it lives in ONE place); any other string renders literally; omit to hide."
      },
      "meta": {
        "kind": "unknown",
        "design": "plumbing",
        "optional": true,
        "description": "Muted row under the title. EXPLICIT-ONLY: omitted (or null) renders nothing; pass any node to render it. (The old data-bound NAP + status Badge default was dropped — the location already leads the breadcrumb.) (default none)"
      },
      "actions": {
        "kind": "unknown",
        "design": "plumbing",
        "optional": true,
        "description": "Right-aligned actions (Buttons, menus). Rendered shrink-0 beside the title block."
      },
      "help": {
        "kind": "boolean",
        "design": "knob",
        "optional": true,
        "description": "Help/support entry top-right on every page (quiet \"?\" icon button opening a support popover). Pass help={false} to hide on a screen. (default true)"
      },
      "align": {
        "kind": "enum",
        "values": [
          "center",
          "justify"
        ],
        "design": "knob",
        "optional": true,
        "description": "Where the header CONTENT sits inside the full-width band the shell paints. \"center\" (default) caps it at the DS content width (--breakpoint-lg) and CENTRES it, so it lines up exactly with the body (GlobalLayoutContent centres the same way — a left-aligned header drifts right of the body at wide viewports; this is the fix). \"justify\" drops the cap so crumbs/title pin hard-left and actions hard-right at the column edges (full-width toolbar look). Almost every page wants \"center\". (default \"center\")"
      },
      "dataHook": {
        "kind": "string",
        "design": "plumbing",
        "optional": true,
        "description": "Instance name. (default \"page-header\")"
      }
    }
  },
