  "VirtualizedDataTable": {
    "name": "VirtualizedDataTable",
    "props": {
      "height": {
        "kind": "number",
        "design": "knob",
        "optional": true,
        "description": "Height of the scroll container in pixels. Required — virtualization needs a bounded viewport. Pass a CSS value via `className` instead if you need responsive heights (e.g. `className=\"h-[80vh]\"`), and omit this prop."
      },
      "estimateSize": {
        "kind": "number",
        "design": "knob",
        "optional": true,
        "default": 48,
        "description": "Estimated height of a single row in pixels. The virtualizer uses this for initial layout before measuring real DOM nodes."
      },
      "overscan": {
        "kind": "number",
        "design": "knob",
        "optional": true,
        "default": 5,
        "description": "Number of rows to render outside the visible viewport. Higher values reduce blank-flash on fast scrolling at the cost of more DOM nodes."
      },
      "table": {
        "kind": "unknown",
        "design": "plumbing",
        "description": "TanStack Table instance (usually returned from `useDataTable`)."
      },
      "dataHook": {
        "kind": "string",
        "design": "plumbing",
        "description": "Data hook for automated testing (REQUIRED)."
      },
      "trackingEl": {
        "kind": "string",
        "design": "knob",
        "optional": true,
        "description": "Analytics element identifier."
      },
      "trackingLabel": {
        "kind": "string",
        "design": "knob",
        "optional": true,
        "description": "Analytics label."
      },
      "isLoading": {
        "kind": "boolean",
        "design": "knob",
        "optional": true,
        "description": "Show skeleton rows instead of data while loading async data."
      },
      "skeletonRowCount": {
        "kind": "number",
        "design": "knob",
        "optional": true,
        "description": "Number of skeleton rows when loading. Falls back to the table's page size, then 10."
      },
      "noResultsMessage": {
        "kind": "string",
        "design": "knob",
        "optional": true,
        "default": "No results.",
        "description": "Empty state message."
      },
      "stickyHeader": {
        "kind": "boolean",
        "design": "knob",
        "optional": true,
        "default": false,
        "description": "Pin the `<thead>` to the top of the scroll container so column headers remain visible while scrolling. The header keeps its opaque `bg-muted` background to separate it from body rows."
      },
      "layout": {
        "kind": "enum",
        "values": [
          "auto",
          "fixed"
        ],
        "design": "knob",
        "optional": true,
        "default": "auto",
        "description": "Table layout algorithm. - `\"auto\"` (default) — browser sizes columns based on content. - `\"fixed\"` — columns respect explicit `width` values on `TableHead`/`TableCell` and split remaining space equally. Use when you set `width` on headers. **Migration note:** `\"fixed\"` will become the default in the next major release. Consumers should start setting explicit `width` on columns now."
      },
      "minWidth": {
        "kind": "string",
        "design": "knob",
        "optional": true,
        "description": "Minimum width for the table (e.g., \"1100px\", \"60rem\"). Prevents columns from compressing on narrow viewports and enables horizontal scroll. When set, the scroll container becomes a focusable region for keyboard accessibility."
      },
      "scrollRegionLabel": {
        "kind": "string",
        "design": "knob",
        "optional": true,
        "default": "Scrollable table",
        "description": "Accessible label for the scroll container region. Used when `minWidth` is set to provide context for keyboard users."
      },
      "footer": {
        "kind": "unknown",
        "design": "content",
        "optional": true,
        "description": "Optional footer rendered inside the `<table>` element after `<tbody>`. Use for summary rows or totals. Pass a `<TableFooter>` with rows."
      }
    },
    "variantDefaults": {
      "layout": "auto"
    }
  },
